// The gallery's sound boot: one module script per page (r4/ex/build.mjs page() adds it before gallery.js). It creates
// nothing and fetches nothing; the visitor's first gesture brings the slice manifest, the kit and the room theme, and
// the first press's files beside the manifest (their entries below). The press's own two Opus files ride here as
// base64 (inline), decoded on the first gesture with no request. Paths resolve from this file, so a card page three
// folders deep boots the same way as the home page. Written by tools/mix.mjs from manifest.json; do not edit.
import Sound from './sound.js';

globalThis.Sound = Sound;
Sound.init({ manifest: new URL('manifest.gallery.json', import.meta.url).href, page: 'gallery', groups: ['gallery'], first: {"ui.press":{"group":"gallery","files":["gallery/ui.press-1","gallery/ui.press-2"],"cue":{"bus":"ui","group":"gallery","kind":"click","files":["gallery/ui.press-1","gallery/ui.press-2"],"peakMs":[15,15],"trimDb":[0.28,-0.24],"trimDbAac":[-3.01,-2.86],"gainDb":0,"cooldownMs":40,"jitter":{"cents":25,"db":1},"sync":{"anchor":"event","align":"onset"},"priority":2}},"ui.tap":{"group":"gallery","files":["gallery/ui.tap-1","gallery/ui.tap-2"]},"ui.hover":{"group":"gallery","files":["gallery/ui.hover-1","gallery/ui.hover-2","gallery/ui.hover-3"]},"ui.sound.on":{"group":"gallery","files":["gallery/ui.sound.on-1","gallery/ui.sound.on-2"]}}, inline: {"gallery/ui.press-1":"","gallery/ui.press-2":""} });
Sound.bindToggle(document.getElementById('sound'));
Sound.music('mus.gallery', { fade: 4000 }); // starts after the first gesture, never before
